using System.Net;
using System.Net.Http.Headers;
using System.Net.Http.Json;
using BARANG.Core.Application.Orders;
using BARANG.Core.Domain.Catalog;
using BARANG.Core.Domain.Customers;
using BARANG.Core.Domain.Organization;
using BARANG.Core.Infrastructure.Persistence;
using Xunit;

namespace BARANG.Core.IntegrationTests.Database;

[Collection(PostgreSqlDatabaseFixture.CollectionName)]
public sealed class OrderE2ETests(PostgreSqlDatabaseFixture database)
{
    [Fact] public async Task DraftItemSubmitSearchTimelineConcurrencyCancellationAndIsolationFlow() { await database.ResetAsync(TestContext.Current.CancellationToken); Guid company = Guid.NewGuid(), other = Guid.NewGuid(), branch = Guid.NewGuid(), customer = Guid.NewGuid(); DateTimeOffset now = DateTimeOffset.UtcNow; Product product; ProductVariant variant; await using (CoreDbContext db = database.CreateAdministrationCoreDbContext()) { db.Companies.AddRange(Company.Create(company, "ORDER_E2E", "Order E2E", now).Value, Company.Create(other, "ORDER_OTHER", "Other", now).Value); db.Branches.Add(Branch.Create(branch, company, "MAIN", "Main", now).Value); db.Customers.Add(Customer.Create(customer, company, "C-100", CustomerType.Organization, null, null, null, "Buyer Ltd", null, null, null, null, null, null, null, now).Value); product = Product.Create(Guid.NewGuid(), company, "P-100", "T-Shirt", null, "APPAREL", "PCS", now).Value; variant = ProductVariant.Create(Guid.NewGuid(), product, "SKU-100", "Large Blue", null, "L", "BLUE", now).Value; db.Products.Add(product); db.ProductVariants.Add(variant); await db.SaveChangesAsync(TestContext.Current.CancellationToken); } await using PostgreSqlCoreApiFactory factory = new(database.ConnectionString); using HttpClient client = factory.CreateClient(); using HttpRequestMessage bootstrap = new(HttpMethod.Post, "/api/v1/security/bootstrap") { Content = JsonContent.Create(new { companyId = company, username = "order-admin", displayName = "Order Administrator", password = "StrongOrderPassword123" }) }; bootstrap.Headers.Add("X-Bootstrap-Secret", "test-bootstrap-secret-123456789"); (await client.SendAsync(bootstrap, TestContext.Current.CancellationToken)).EnsureSuccessStatusCode(); Login login = (await (await client.PostAsJsonAsync("/api/v1/auth/login", new { username = "order-admin", password = "StrongOrderPassword123" }, TestContext.Current.CancellationToken)).Content.ReadFromJsonAsync<Login>(TestContext.Current.CancellationToken))!; await Send<object>(client, Req(HttpMethod.Post, "/api/v1/auth/me/company", login.AccessToken, null, new { companyId = company })); OrderView draft = await Send<OrderView>(client, Req(HttpMethod.Post, "/api/v1/orders", login.AccessToken, company, new { branchId = branch, customerId = customer, source = "Internal", orderDate = "2026-08-31", requestedDeliveryDate = "2026-09-10", shippingAddress = new { recipientName = "Receiver", countryCode = "IR", city = "Tehran", addressLine1 = "Street 1" } })); Assert.Equal("Draft", draft.Status.ToString()); using (HttpResponseMessage incomplete = await client.SendAsync(Req(HttpMethod.Post, $"/api/v1/orders/{draft.Id}/submit", login.AccessToken, company, new { version = draft.Version }), TestContext.Current.CancellationToken)) Assert.Equal(HttpStatusCode.BadRequest, incomplete.StatusCode); OrderItemView item = await Send<OrderItemView>(client, Req(HttpMethod.Post, $"/api/v1/orders/{draft.Id}/items", login.AccessToken, company, new { productId = product.Id, productVariantId = variant.Id, quantity = 2, notes = "first" })); Assert.Equal(1, item.LineNumber); draft = await Send<OrderView>(client, Req(HttpMethod.Get, $"/api/v1/orders/{draft.Id}", login.AccessToken, company)); OrderView submitted = await Send<OrderView>(client, Req(HttpMethod.Post, $"/api/v1/orders/{draft.Id}/submit", login.AccessToken, company, new { version = draft.Version })); Assert.StartsWith("ORD-2026-", submitted.OrderNumber, StringComparison.Ordinal); Assert.Equal("P-100", submitted.Items.Single().Snapshot.ProductCode); OrderView retry = await Send<OrderView>(client, Req(HttpMethod.Post, $"/api/v1/orders/{draft.Id}/submit", login.AccessToken, company, new { version = 1 })); Assert.Equal(submitted.OrderNumber, retry.OrderNumber); using (HttpResponseMessage stale = await client.SendAsync(Req(HttpMethod.Put, $"/api/v1/orders/{draft.Id}", login.AccessToken, company, new { branchId = branch, customerId = customer, orderDate = "2026-08-31", version = 1 }), TestContext.Current.CancellationToken)) Assert.Equal(HttpStatusCode.Conflict, stale.StatusCode); using (HttpResponseMessage remove = await client.SendAsync(Req(HttpMethod.Post, $"/api/v1/orders/{draft.Id}/items/{item.Id}/remove", login.AccessToken, company, new { version = item.Version }), TestContext.Current.CancellationToken)) Assert.Equal(HttpStatusCode.UnprocessableEntity, remove.StatusCode); OrderTimelineView[] timeline = await Send<OrderTimelineView[]>(client, Req(HttpMethod.Get, $"/api/v1/orders/{draft.Id}/timeline", login.AccessToken, company)); Assert.Contains(timeline, x => x.EventType == "Submitted"); Page<OrderSummaryView> search = await Send<Page<OrderSummaryView>>(client, Req(HttpMethod.Get, $"/api/v1/orders?orderNumber={submitted.OrderNumber}", login.AccessToken, company)); Assert.Single(search.Items); OrderView cancelled = await Send<OrderView>(client, Req(HttpMethod.Post, $"/api/v1/orders/{draft.Id}/cancel", login.AccessToken, company, new { reasonCode = "CUSTOMER_REQUEST", reasonText = "duplicate", version = submitted.Version })); Assert.Equal("Cancelled", cancelled.Status.ToString()); using (HttpResponseMessage denied = await client.SendAsync(Req(HttpMethod.Get, $"/api/v1/orders/{draft.Id}", login.AccessToken, other), TestContext.Current.CancellationToken)) Assert.Equal(HttpStatusCode.NotFound, denied.StatusCode); await Send<object>(client, Req(HttpMethod.Post, "/api/v1/auth/logout", login.AccessToken, null)); }
    private static HttpRequestMessage Req(HttpMethod method, string uri, string token, Guid? company, object? body = null) { HttpRequestMessage r = new(method, uri); r.Headers.Authorization = new AuthenticationHeaderValue("Bearer", token); if (company is not null) r.Headers.Add("X-Company-ID", company.ToString()); if (body is not null) r.Content = JsonContent.Create(body); return r; }
    private static async Task<T> Send<T>(HttpClient client, HttpRequestMessage request) { using HttpResponseMessage response = await client.SendAsync(request, TestContext.Current.CancellationToken); string payload = await response.Content.ReadAsStringAsync(TestContext.Current.CancellationToken); Assert.True(response.IsSuccessStatusCode, $"{response.StatusCode}: {payload}"); if (typeof(T) == typeof(object) || string.IsNullOrWhiteSpace(payload)) return (T)(object)new(); return (await response.Content.ReadFromJsonAsync<T>(TestContext.Current.CancellationToken))!; }
    private sealed record Login(string AccessToken);
}


